import {chapters,events,assets,items,version,rewardCatalog} from './data.mjs';
import {validateEconomyState,optionAvailable,effectFor,reserveEconomy,economicPreview} from './economy.mjs';
export {createRewardState,confirmPermanentReward,optionAvailable} from './economy.mjs';
import {engineByTemplate,worldPrompt,finalCheckPrompt} from './prompts.mjs';
import {assertCampaignSequence,markRunFailed,buildChapterRecord,chapterReviewFacts} from './review.mjs';
export {chapterReviewFacts,fallbackRecap} from './review.mjs';
export {chapters,events,assets,items,version,rewardCatalog};
export const matrix={start:['新一轮事件'],next_round:['新一轮事件'],choose:['检定','战斗事件','结算'],settle_check:['结算'],battle_result:['结算'],finale:['终章']};
const copy=x=>structuredClone(x);
function need(ok,msg){if(!ok)throw new Error(msg)}
export function yaml(value,depth=0){const pad=' '.repeat(depth);if(Array.isArray(value))return value.length?value.map(v=>typeof v==='object'&&v!==null?pad+'-\n'+yaml(v,depth+2):pad+'- '+JSON.stringify(v)).join('\n'):pad+'[]';return Object.entries(value).map(([k,v])=>{if(v&&typeof v==='object'&&Object.keys(v).length)return pad+k+':\n'+yaml(v,depth+2);return pad+k+': '+JSON.stringify(v)}).join('\n')}
export function getChapter(id){const c=chapters.find(x=>x.id===id);need(c,'非法chapter_id');return c}
export function getStageForRound(chapterId,round){const c=getChapter(chapterId);need(Number.isInteger(round)&&round>=1&&round<=c.count,'章内轮数越界');return c.stages.find(x=>round>=x.start&&round<=x.end).id}
export function getScheduledEventIds(runtime){const c=getChapter(runtime.chapter_id);const round=runtime.current_round;getStageForRound(c.id,round);const done=new Set(runtime.story_state.completed_events.map(x=>x.event_id));const all=Object.values(events).filter(e=>e.chapter_id===c.id&&round>=e.schedule.round_min&&round<=e.schedule.round_max&&!done.has(e.event_id));const fixed=all.filter(e=>e.schedule.fixed);return (fixed.length?fixed:all).map(e=>e.event_id).sort()}
export function newCampaign(id){need(typeof id==='string'&&id.length>0,'campaign_id不能为空');return {schema_version:3,campaign_id:id,revision:0,status:'ongoing',chapter_results:[],story_flags:[],npc_states:[],key_items:[],memory_notes:[],unresolved_hooks:[]}}
function createBaseRun({campaign,chapterId,runId,seed,team,relics=[],gold=0,diamond=0,mode='story',difficulty='normal',rewardState}){
 const c=getChapter(chapterId);assertCampaignSequence(campaign);need(rewardState,'必须传入当前账号章节奖励账本，禁止从入口重置');need(mode==='story','本版禁止replay；只能继续本次冒险或从CH01重开');need(['normal','hard','nightmare'].includes(difficulty),'非法难度');need(Number.isSafeInteger(seed),'seed必须整数');need(typeof runId==='string'&&runId.length>0,'run_id不能为空');need(team.length>=1&&team.length<=4,'队伍1-4人');
 need(c.index===1||campaign.chapter_results.some(x=>x.chapter_id===chapters[c.index-2].id),'前章尚未确认通关');
 if(mode==='story'){need(campaign.status==='ongoing','已完结主线不能继续');need(campaign.chapter_results.length===c.index-1,'主线只允许推进下一章')}
 const relevant=campaign.story_flags.filter(f=>c.import_flags.includes(f));
 const supply=Math.min(100,c.initial_supply+(relevant.includes('TOWN_SUPPLY_SECURED')?5:0));
 const archetypes=['corruption_hunt','scarcity','ghost_tide','underworld','time_fracture'];
 campaign=copy(campaign); // 不修改调用者存档
 return {package_context:{engine:{id:'adventure.engine.chapter',version},world:{id:'world.witchhunter',version},dungeon:{id:'witchhunter.'+chapterId,version}},campaign_id:campaign.campaign_id,campaign_revision:campaign.revision,chapter_id:chapterId,play_mode:mode,run_id:runId,state_version:1,run_difficulty:difficulty,run_seed:seed,current_round:1,current_scene_id:c.stages[0].scene_id,corruption_value:10,supply_value:supply,run_status:'ongoing',team_status:'active',current_package:{relics:copy(relics),tools:copy(campaign.key_items)},current_team:copy(team),gold,diamond,gold_policy:{allow_gain:true,allow_cost:true,max_gain_per_event:c.economy.max_gold_gain_per_event,max_cost_per_event:c.economy.max_gold_cost_per_event},diamond_policy:{allow_gain:false,allow_cost:false,max_gain_per_event:0,max_cost_per_event:0},story_state:{completed_events:[],story_flags:copy(campaign.story_flags),route_scores:{combat:0,scheme:0,cleanse:0},current_scene_id:c.stages[0].scene_id,visited_scene_ids:[c.stages[0].scene_id],npc_states:copy(campaign.npc_states),unresolved_hooks:copy(campaign.unresolved_hooks),memory_notes:copy(campaign.memory_notes),recent_event_ids:[],run_archetype:archetypes[Math.abs(seed)%5],run_modifier_ids:['MOD_GHOST_TIDE','MOD_FRACTURED_TRUST']},world_story_state:copy(campaign),reward_state:copy(rewardState),pending_interaction:null,recent_run_summaries:[],applied_request_ids:[]};
}
export function createChapterRun(args){const r=createBaseRun(args);validateEconomyState(r);const plans=getChapter(r.chapter_id).hidden_plan;if(plans.length)r.story_state.story_flags.push(plans[Math.abs(r.run_seed)%plans.length].plan);return r}
export function freezeChapterEntry(runtime){need(runtime.current_round===1&&!runtime.pending_interaction,'只允许开局保存入口');return copy(runtime)}
export function retryChapter(){throw new Error('禁止重试当前章或中间章；调用restartAdventure从CH01建立新campaign')}
export function request(runtime,operation){return {...copy(runtime),operation:copy(operation)}}
function validateRequest(r){
 validateEconomyState(r);
 assertCampaignSequence(r.world_story_state);need(r.play_mode==='story','禁止replay请求');need(r.world_story_state.status==='ongoing','已结束冒险不能发起新请求');need(r.world_story_state.chapter_results.length===getChapter(r.chapter_id).index-1,'章节游标与前章记录不一致');
 const c=getChapter(r.chapter_id),op=r.operation;need(op&&matrix[op.type]?.includes(op.expected_template_name),'operation与模板不匹配');need(typeof op.request_id==='string'&&op.request_id.length>0,'缺少request_id');getStageForRound(c.id,r.current_round);
 need(r.campaign_id===r.world_story_state.campaign_id&&r.campaign_revision===r.world_story_state.revision,'跨章存档版本不一致');
 need(r.current_scene_id===r.story_state.current_scene_id,'场景快照不一致');need(r.current_team.length>=1&&r.current_team.length<=4,'队伍数量越界');
 for(const [key,id] of [['engine','adventure.engine.chapter'],['world','world.witchhunter'],['dungeon','witchhunter.'+c.id]])need(r.package_context?.[key]?.id===id&&r.package_context[key].version===version,'包版本不一致');
 if(['start','next_round'].includes(op.type)){need(r.run_status==='ongoing'&&r.pending_interaction===null,'新事件状态非法');if(op.type==='start')need(r.current_round===1,'start只能用于首轮')}
 else if(op.type==='finale')need(['cleared','failed'].includes(r.run_status)&&!r.pending_interaction,'收尾须在章结束后');
 else {const p=r.pending_interaction;need(p&&events[p.event_id]?.chapter_id===c.id,'缺少合法pending');need(op.event_id===p.event_id&&op.option_id===p.option_id,'选项/事件快照不一致');need(p.event_output?.event_details?.template_name==='新一轮事件','event_output必须为完整根对象');need(p.selected_option?.id===op.option_id,'缺少选项快照');need(p.scene_id===r.current_scene_id,'pending场景不一致');
 if(op.type==='choose'){need(p.phase==='awaiting_choice','choose phase错误');need(JSON.stringify(op.selected_option)===JSON.stringify(p.selected_option),'selected_option不一致');need(op.expected_template_name===p.selected_option.template_name,'选择路由错误');need(!p.resolution_output,'choose不得携带resolution_output')}
 if(op.type==='settle_check'){need(p.phase==='awaiting_settlement_commit','结算phase错误');need(p.resolution_output?.event_details?.template_name==='检定','缺少完整检定输出');need(op.check_result===p.resolution_output.event_details.result,'检定结果不一致')}
 if(op.type==='battle_result'){need(p.phase==='awaiting_settlement_commit','结算phase错误');need(p.resolution_output?.event_details?.template_name==='战斗事件','缺少完整战斗输出');need(['victory','defeat','retreat'].includes(op.battle_result),'非法战斗结果')}
 }
}
export function prepareAiMessages(r){validateRequest(r);const c=getChapter(r.chapter_id),op=r.operation;const mode=['start','next_round'].includes(op.type)?'event_generation':op.type==='finale'?'finale':'active_event';let ids=mode==='event_generation'?getScheduledEventIds(r):mode==='active_event'?[r.pending_interaction.event_id]:[];
 if(op.forced_event_id){need(mode==='event_generation'&&ids.includes(op.forced_event_id),'非法强制事件');need(events[op.forced_event_id].kind!=='hidden','程序不可跳过隐藏前置强制隐藏事件');ids=[op.forced_event_id]}
 if(r.event_candidates){need(mode==='event_generation'&&r.event_candidates.length>0,'非法候选列表');const eligible=new Set(ids);need(r.event_candidates.every(e=>eligible.has(e.event_id)&&Number.isInteger(e.weight)&&e.weight>0),'候选越界');ids=r.event_candidates.map(x=>x.event_id);need(new Set(ids).size===ids.length,'候选重复');if(op.forced_event_id)need(ids.includes(op.forced_event_id),'候选不含强制事件')}
 const roleNames=new Set(),sceneIds=new Set();for(const id of ids){events[id].asset_scope.roles.forEach(x=>roleNames.add(x));events[id].asset_scope.scenes.forEach(x=>sceneIds.add(x))}if(mode==='event_generation')sceneIds.add(r.current_scene_id);
 const chapterRules={chapter_id:c.id,name:c.name,goal:c.goal,count:c.count,stage:getStageForRound(c.id,r.current_round),imports:c.import_rules,exports:c.export_flags,chapter_rules:c.rules,economy:c.economy,hidden_plan:c.hidden_plan,ending:c.ending,item_catalog:items};
 const bricks=[{id:'engine.'+op.expected_template_name,content:engineByTemplate[op.expected_template_name]},{id:'world',content:worldPrompt},{id:'chapter.'+c.id+'.'+mode,content:'#章节规则\n'+yaml(chapterRules)+(mode==='finale'?'\n本次只写当前章收尾；CH08才回收整个世界主线。':'\n#允许事件\n'+yaml({included_event_ids:ids,events:ids.map(id=>events[id])}))},{id:'assets',content:mode==='event_generation'?'#当前候选资产\n'+yaml({roles:[...roleNames].map(name=>assets.roles[name]),scenes:[...sceneIds].map(id=>assets.scenes[id])}):mode==='active_event'?'#当前事件资产\n'+yaml({roles:[...roleNames].map(name=>assets.roles[name]),scenes:[...sceneIds].map(id=>assets.scenes[id])}):''},{id:'final_check',content:finalCheckPrompt}];
 const aiRuntime=copy(r);if(mode==='event_generation')aiRuntime.effective_event_options=Object.fromEntries(ids.map(id=>[id,economicPreview(r,events[id])]));if(mode==='active_event')aiRuntime.settlement_preview=economicPreview(r,events[r.pending_interaction.event_id]).find(x=>x.option_id===r.pending_interaction.option_id);delete aiRuntime.applied_request_ids;delete aiRuntime.reward_requests;delete aiRuntime.chapter_journal;delete aiRuntime.terminal_tools;aiRuntime.world_story_state.chapter_results=aiRuntime.world_story_state.chapter_results.map(({chapter_id,run_id,outcome,flags})=>({chapter_id,run_id,outcome,flags}));if(mode==='finale')aiRuntime.chapter_review_facts=chapterReviewFacts(r);const systemPrompt=bricks.filter(b=>b.content).map(b=>b.content).join('\n\n');const userPrompt='#本次程序运行态输入\n'+yaml(aiRuntime);return {systemPrompt,userPrompt,fullPrompt:systemPrompt+'\n\n'+userPrompt,bricks,contextScope:{mode,chapter_id:c.id,stage:chapterRules.stage,included_event_ids:ids}};
}
export function acceptNewEvent(runtime,output){const r=copy(runtime),d=output.event_details,e=events[d.event_id];need(!r.pending_interaction&&r.run_status==='ongoing','已有交互或章节已结束');need(d.current_round===r.current_round&&d.supply_value===r.supply_value&&d.corruption_value===r.corruption_value,'新事件快照不一致');need(d.template_name==='新一轮事件'&&getScheduledEventIds(r).includes(d.event_id),'新事件越界');need(e.asset_scope.scenes.some(id=>assets.scenes[id].name===d.scene_name),'场景越界');if(e.kind==='hidden'){need(e.requires.all_flags.every(f=>r.story_state.story_flags.includes(f)),'隐藏前置不足');need(!r.story_state.completed_events.some(x=>events[x.event_id]?.kind==='hidden'),'本章隐藏额度用尽')}
 const sid=e.asset_scope.scenes.find(id=>assets.scenes[id].name===d.scene_name);need(d.options.length===e.options.length,'选项数量错误');for(const o of d.options){const def=e.options.find(x=>x.id===o.id);need(def&&o.template_name===({check:'检定',battle:'战斗事件',direct:'结算'})[def.resolution_type],'选项路由错误');need(o.available===optionAvailable(r,def),'选项道具可用性错误')}
 r.current_scene_id=sid;r.story_state.current_scene_id=sid;r.story_state.visited_scene_ids=[...new Set([...r.story_state.visited_scene_ids,sid])];r.pending_interaction={event_id:e.event_id,phase:'awaiting_choice',scene_id:sid,scene_name:d.scene_name,event_output:copy(output)};r.state_version++;return r;
}
export function selectOption(runtime,id){const r=copy(runtime),p=r.pending_interaction;need(p?.phase==='awaiting_choice'&&!p.selected_option,'不能选择或重复改选');const o=p.event_output.event_details.options.find(x=>x.id===id);need(o&&o.visible&&o.available&&optionAvailable(r,events[p.event_id].options.find(x=>x.id===id)),'选项不可用');p.option_id=id;p.selected_option=copy(o);r.state_version++;return r}
export function acceptResolution(runtime,output){const r=copy(runtime),p=r.pending_interaction;need(p&&p.phase==='awaiting_choice','不能接受执行结果');need(output.event_details.template_name===p.selected_option.template_name,'执行模板错误');p.resolution_output=copy(output);p.phase=output.event_details.template_name==='检定'?'awaiting_settlement_commit':'awaiting_battle_result';r.state_version++;return r}
export function acceptBattleResult(runtime,result){need(['victory','defeat','retreat'].includes(result),'战斗结果非法');const r=copy(runtime);need(r.pending_interaction?.phase==='awaiting_battle_result','无正在等待的战斗');r.pending_interaction.phase='awaiting_settlement_commit';r.pending_interaction.battle_result=result;r.state_version++;return r}
export function settlementEffect(runtime,outcome){const p=runtime.pending_interaction;return effectFor(runtime,p.event_id,p.option_id,outcome)}
export function commitSettlement(runtime,output,{requestId,expectedVersion}){
 need(expectedVersion===runtime.state_version,'过期state_version');need(!runtime.applied_request_ids.includes(requestId),'重复结算');const r=copy(runtime),d=output.event_details,p=r.pending_interaction;need(d.template_name==='结算'&&p&&d.event_id===p.event_id,'结算事件错误');need(d.scene_name===p.scene_name,'结算场景错误');const patch=d.story_patch;need(patch.completed_event_id===p.event_id&&patch.selected_option_id===p.option_id,'story_patch标识错误');const {event:e,option:o,effect:fx}=settlementEffect(r,patch.outcome);
 if(o.resolution_type==='check')need(({大成功:'great_success',成功:'success',失败:'failure'})[p.resolution_output?.event_details.result]===patch.outcome,'检定结果映射错误');
 if(o.resolution_type==='direct')need(patch.outcome==='resolved','直接结算结果错误');
 if(o.resolution_type==='battle')need(p.battle_result===patch.outcome,'战斗结果映射错误');
 need(d.current_round===r.current_round&&d.supply_value===r.supply_value&&d.corruption_value===r.corruption_value,'结算前状态快照错误');
 need(JSON.stringify([...patch.add_flags].sort())===JSON.stringify([...fx.add_flags].filter(f=>!r.story_state.story_flags.includes(f)).sort()),'未按事件授权添加flag');
 need(JSON.stringify([...patch.remove_flags].sort())===JSON.stringify(fx.remove_flags.filter(f=>r.story_state.story_flags.includes(f)).sort()),'未按事件授权移除flag');
 need(JSON.stringify(patch.route_delta)===JSON.stringify(fx.route_delta),'路线变化不合法');need(patch.run_archetype===r.story_state.run_archetype&&JSON.stringify(patch.run_modifier_ids)===JSON.stringify(r.story_state.run_modifier_ids),'不可改写本局配置');
 const actualItems=d.summary.filter(x=>x.type==='item').map(({id,count})=>({id,count}));need(JSON.stringify(actualItems)===JSON.stringify(fx.items),'物品变化不合法');
 const attrs=d.summary.filter(x=>x.type==='player_attr');const expectedAttrs=Object.fromEntries(Object.entries(fx.resources).filter(([,v])=>v!==0));need(attrs.length===(Object.keys(expectedAttrs).length?1:0),'资源项数量错误');if(attrs.length)need(JSON.stringify(Object.fromEntries(Object.entries(attrs[0]).filter(([k])=>k!=='type')))===JSON.stringify(expectedAttrs),'资源变化不合法');
 need(JSON.stringify(patch.npc_state_updates)===JSON.stringify(fx.npc_updates),'NPC变化未获授权');
 for(const u of fx.npc_updates){const old=r.story_state.npc_states.find(n=>n.npc===u.npc);need(!old||!['dead','departed'].includes(old.state)||old.state===u.state,'不可恢复终态NPC');if(old)old.state=u.state;else r.story_state.npc_states.push(copy(u))}
 for(const x of fx.items){const def=items.find(t=>t.id===x.id);need(def,'道具未定义');if(def.kind==='reward_signal'){need(x.count===1,'奖励信号数量错误');continue}let owned=r.current_package.tools.find(t=>t.id===x.id);need((owned?.count??0)+x.count>=0,'道具不足');if(!owned){owned={id:x.id,name:def.name,count:0};r.current_package.tools.push(owned)}owned.count+=x.count;need(owned.count<=def.max_count,'唯一道具重复获得')}
 reserveEconomy(r,e,fx,requestId);r.current_package.tools=r.current_package.tools.filter(x=>x.count>0);r.corruption_value=Math.max(0,r.corruption_value+(fx.resources.corruption??0));r.supply_value=Math.min(100,r.supply_value+(fx.resources.supply??0));
 const hard=r.corruption_value>=100||r.supply_value<=0||r.team_status==='defeated';const status=hard?'failed':fx.finish;
 need(d.final_chapter===(status!=='ongoing'),'章节结束标记错误');r.run_status=status;
 r.chapter_journal??=[];r.chapter_journal.push({event_id:e.event_id,round:r.current_round,option_id:o.id,outcome:patch.outcome,npc_updates:copy(fx.npc_updates),item_changes:copy(fx.items.filter(x=>items.find(i=>i.id===x.id)?.kind==='tool'))});markRunFailed(r);
 r.story_state.story_flags=[...new Set([...r.story_state.story_flags.filter(f=>!fx.remove_flags.includes(f)),...fx.add_flags])];
 r.story_state.completed_events.push({event_id:e.event_id,option_id:o.id,outcome:patch.outcome});for(const k of ['combat','scheme','cleanse'])r.story_state.route_scores[k]+=fx.route_delta[k];
 need(patch.memory_notes.length<=3,'记忆最多3条');need(patch.unresolved_hooks_added.length<=1,'新增悬念最多1条');need(patch.unresolved_hooks_resolved.every(x=>r.story_state.unresolved_hooks.includes(x)),'不能解决不存在悬念');r.story_state.memory_notes=[...r.story_state.memory_notes,...patch.memory_notes];r.story_state.unresolved_hooks=[...new Set([...r.story_state.unresolved_hooks.filter(x=>!patch.unresolved_hooks_resolved.includes(x)),...patch.unresolved_hooks_added])];need(r.story_state.unresolved_hooks.length<=3,'悬念超过3条');r.story_state.recent_event_ids=[...r.story_state.recent_event_ids,e.event_id].slice(-3);r.pending_interaction=null;r.state_version++;r.applied_request_ids.push(requestId);return r;
}
export function nextRound(runtime){const r=copy(runtime);need(r.run_status==='ongoing'&&!r.pending_interaction,'不能推进轮次');need(r.story_state.completed_events.length===r.current_round,'必须完成本轮且不得重复推进');need(r.current_round<getChapter(r.chapter_id).count,'末轮必须结算结束');r.current_round++;r.supply_value-=({normal:1,hard:2,nightmare:3})[r.run_difficulty];if(r.supply_value<=0||r.corruption_value>=100||r.team_status==='defeated')r.run_status='failed';markRunFailed(r);r.state_version++;return r}
export function promoteChapter(campaign,runtime,options={}){const c=getChapter(runtime.chapter_id);assertCampaignSequence(campaign);need(campaign.status==='ongoing','冒险已结束');need(runtime.play_mode==='story','重刷不得改写主线');need(runtime.run_status==='cleared'&&!runtime.pending_interaction,'只有已确认通关才能交接');need(campaign.campaign_id===runtime.campaign_id&&campaign.revision===runtime.campaign_revision,'主线版本冲突');need(campaign.chapter_results.length===c.index-1,'重复或越章提交');need(runtime.story_state.completed_events.length===c.count&&runtime.story_state.completed_events.at(-1)?.event_id===c.ending.event_id,'章末完整进度未提交');need(!(runtime.reward_requests??[]).some(q=>q.status==='pending'),'先完成已预留奖励确认，再提交章节');
 const allowed=new Set(chapters.slice(0,c.index).flatMap(x=>x.export_flags));const next=copy(campaign);next.story_flags=runtime.story_state.story_flags.filter(f=>allowed.has(f));next.key_items=copy(runtime.current_package.tools.filter(t=>items.find(x=>x.id===t.id)?.carry_through_chapter>c.index));next.npc_states=copy(runtime.story_state.npc_states);next.memory_notes=[...new Set(runtime.story_state.memory_notes)].slice(-24);next.unresolved_hooks=copy(runtime.story_state.unresolved_hooks);next.chapter_results.push(buildChapterRecord(runtime,options));next.revision++;if(c.index===8){next.status='completed';next.key_items=[]}return next;
}
export function failCampaign(campaign,runtime,options={}){assertCampaignSequence(campaign);need(campaign.status==='ongoing'&&runtime.run_status==='failed'&&!runtime.pending_interaction,'必须为已失败的当前冒险');need(campaign.campaign_id===runtime.campaign_id&&campaign.revision===runtime.campaign_revision,'失败记录版本冲突');need(campaign.chapter_results.length===getChapter(runtime.chapter_id).index-1,'失败章节不连续或已归档');const next=copy(campaign);next.status='failed';next.key_items=[];next.npc_states=copy(runtime.story_state.npc_states);next.chapter_results.push(buildChapterRecord(runtime,options));next.revision++;return next}
